grant all on fx to authenticated;

do $$
declare res jsonb; first_batch uuid; manual uuid;
begin
  res := import_duties((select payload from fx));
  first_batch := (res ->> 'batch_id')::uuid;
  perform pg_temp.assert_eq((res ->> 'rows_read')::int, 30, '30 rows read');
  perform pg_temp.assert_eq((res ->> 'duties')::int, 27, '27 duties');
  perform pg_temp.assert_eq((res ->> 'week_offs')::int, 3, '3 week offs');
  perform pg_temp.assert_eq((select payable_days from beta_summary('2026-09-01')), 26, '26 payable days (14 Sep counts once)');
  perform pg_temp.assert_eq((select total_amount from beta_summary('2026-09-01')), 6500::numeric, '26 x 250 = 6,500 (all Local)');
  perform pg_temp.assert_eq((select count(*)::int from driver_day_entries where entry_date = '2026-09-23'), 0, 'gap on 23 Sep');
  perform pg_temp.assert_eq((select vehicle_label from driver_day_entries where entry_date = '2026-09-24'), 'Others · Audi', 'Audi saved as Others');
  perform pg_temp.assert_eq((select count(*)::int from driver_day_entries where entry_date = '2026-09-14'), 2, 'two duties on 14 Sep');
  perform pg_temp.assert_eq((select vehicle_source from driver_day_entries where guest_name = 'Dr. Jaswanth'), 'fleet', 'fleet linked');
  perform pg_temp.assert_eq((select total_km from driver_day_entries where guest_name = 'Dr. Jaswanth'), 93, 'stated total km kept');
  perform pg_temp.assert_eq((select total_minutes from driver_day_entries where guest_name = 'Dr. Jaswanth'), 570, '9 hrs 30 mins kept');
  perform pg_temp.assert_eq((select entry_source from driver_day_entries limit 1), 'import', 'marked as imported');

  -- a hand-entered week off for the gap day; "fill" must not touch existing days; undo removes only the batch
  insert into driver_day_entries (driver_id, entry_date, entry_type, entry_source) values ('00000000-0000-0000-0000-0000000000d1', '2026-09-23', 'week_off', 'app') returning id into manual;
  res := import_duties((select jsonb_set(payload, '{mode}', '"fill"') from fx));
  perform pg_temp.assert_eq((select count(*)::int from driver_day_entries), 31, 'fill added nothing: every day was taken (30 imported + the manual 23 Sep)');
  perform pg_temp.assert_eq(undo_duty_import(first_batch), 30, 'undo removes only that batch');
  perform pg_temp.assert_eq((select count(*)::int from driver_day_entries where entry_source = 'app'), 1, 'hand-entered entry survives undo');
  perform pg_temp.expect_error(format('select undo_duty_import(%L)', first_batch), 'undo twice');
end $$;

-- replace deletes the month first
do $$
declare res jsonb;
begin
  res := import_duties((select jsonb_set(payload, '{mode}', '"replace"') from fx));
  perform pg_temp.assert_eq((res ->> 'replaced')::int, 1, 'replace removed what was there (only the hand-entered day survived the undo)');
  perform pg_temp.assert_eq((select count(*)::int from driver_day_entries), 30, '30 rows after replace');
  -- a duty and a week off on the same date blocks the whole import
  perform pg_temp.expect_error($q$select import_duties('{"driver_id":"00000000-0000-0000-0000-0000000000d1","month":"2026-10-01","mode":"fill","rows":[{"entry_date":"2026-10-09"},{"entry_date":"2026-10-09","entry_type":"week_off"}]}'::jsonb)$q$, 'clash blocks import');
end $$;
